  "evidence": [
   {
    "quote": "Columns of parent/partitioned and child/partition tables must all have the same generation status",
    "source": "PostgreSQL 16 release notes: Migration to Version 16",
    "release_of_change": "16"
   }
  ]
 },
 {
  "condition_id": "generation_expressions_may_differ_betwee_db524a",
  "claim": "Generation expressions may differ between parent and child columns as long as generation status is the same.",
  "evidence": [
   {
    "quote": "though now the actual generation expressions can be different",
    "source": "PostgreSQL 16 release notes: Migration to Version 16",
    "release_of_change": "16"
   }
  ]
 }
]
